 daily.append('if = { limit = { date > 1939.7.31 } FRA = { remove_ideas = hro_history_neubaufahrzeug_fear } ENG = { remove_ideas = hro_history_neubaufahrzeug_fear } }')
 # Rear operations: three finite cells, paid at preparation, no whole-state flip.
 text('hro_rear_cells','Тыловые коллаборационистские ячейки','Rear-Area Collaborationist Cells')
 text('hro_rear_cells_desc','125 ПВ, 600 пехотного оружия и 6000 людских ресурсов; подготовка 21 день. По завершении — две слабые дивизии ополчения в одной сельской провинции советского тыла. СССР получает предупреждение. Каждая область — один раз; общая перезарядка 180 дней. При смене контроля или окончании войны операция отменяется без возврата затрат.','125 PP, 600 infantry equipment and 6,000 manpower; 21-day preparation. On completion, two weak militia divisions appear in one rural Soviet rear province. The USSR receives a warning. Once per region, global 180-day cooldown. Cancellation on control changes or peace gives no refund.')
 template='hro_rear_militia';text(template,'Тыловое вспомогательное ополчение','Rear Auxiliary Militia')
 for key,ru,en,state,province in REGIONS:
  ident='hro_rear_'+key;pending=ident+'_pending';timer=ident+'_timer';used=ident+'_used'
  safe=f'{state} = {{ is_owned_by = SOV is_fully_controlled_by = SOV NOT = {{ any_neighbor_state = {{ controller = {{ has_war_with = SOV }} }} }} }}'
  live='original_tag = GER has_capitulated = no has_war_with = SOV SOV = { exists = yes has_capitulated = no }'
  valid=f'{live} {safe}'
  available=f'{valid} has_manpower > 5999 has_equipment = {{ infantry_equipment > 599 }} NOT = {{ has_country_flag = {used} }} NOT = {{ has_country_flag = hro_rear_global_lock }}'
  text(ident,'Поднять ячейки: '+ru,'Activate Cells: '+en)
  text(ident+'_desc',f'125 ПВ, 600 оружия, 6000 людских ресурсов; 21 день. Две дивизии по три батальона пехоты, 60% оснащения и 10% опыта: провинция {province}, {ru}. Только советская область без соседних областей под контролем воюющих с СССР стран. Передача лишь одной сельской провинции, не всей области. Один запуск в регионе; общий интервал 180 дней. При срыве условий затраты не возвращаются.',f'125 PP, 600 rifles and 6,000 manpower; 21 days. Two three-battalion infantry divisions at 60% equipment and 10% experience in province {province}, {en}. Requires a fully Soviet-controlled state without neighbouring states controlled by countries at war with the USSR. Only one rural province changes control. Once per region; global interval 180 days. No refund on cancellation.')
  decisions.append(f'{ident} = {{ icon = generic_army cost = 125 visible = {{ original_tag = GER has_war_with = SOV }} available = {{ {available} }} complete_effect = {{ hro_rear_begin_{key} = yes }} days_remove = 21 remove_effect = {{ hro_rear_finish_{key} = yes }} ai_will_do = {{ factor = 0 }} }}')
  effects.append(f'''hro_rear_begin_{key} = {{ if = {{ limit = {{ {available} }} set_country_flag = {used} set_country_flag = {pending} set_country_flag = {{ flag = {timer} value = 1 days = 21 }} set_country_flag = {{ flag = hro_rear_global_lock value = 1 days = 180 }} add_equipment_to_stockpile = {{ type = infantry_equipment amount = -600 }} add_manpower = -6000 SOV = {{ country_event = {{ id = hro.955 days = 1 }} }} }} }}
 hro_rear_finish_{key} = {{ if = {{ limit = {{ has_country_flag = {pending} NOT = {{ has_country_flag = {timer} }} }} clr_country_flag = {pending}
  if = {{ limit = {{ {valid} }}
   if = {{ limit = {{ NOT = {{ has_country_flag = hro_rear_template_created }} }} set_country_flag = hro_rear_template_created division_template = {{ name = "{template}" localization_key = {template} is_locked = yes regiments = {{ infantry = {{ x = 0 y = 0 }} infantry = {{ x = 0 y = 1 }} infantry = {{ x = 0 y = 2 }} }} }} }}
   set_province_controller = {province}
   {state} = {{ create_unit = {{ division = "division_template = \\"{template}\\" start_experience_factor = 0.1 start_equipment_factor = 0.6" owner = GER prioritize_location = {province} allow_spawning_on_enemy_provs = yes count = 2 }} }}
  }}
 }} }}''')
  daily.append(f'if = {{ limit = {{ original_tag = GER }} hro_rear_finish_{key} = yes }}')
 event('hro.955','Подполье в нашем тылу','Underground Cells in Our Rear','Разведка сообщает о подготовке вооружённых коллаборационистских ячеек. Противник может попытаться захватить сельский плацдарм и нарушить наши коммуникации. Следует оставить мобильные резервы в Минской, Смоленской и Киевской областях. Сценарий описывает отдельные группы, а не позицию всего населения.','Intelligence reports armed collaborationist cells preparing to seize a rural foothold and disrupt communications. Keep mobile reserves in the Minsk, Smolensk and Kyiv regions. The scenario concerns individual groups, not the views of the entire population.',[('Усилить наблюдение за тылом.','Watch the rear closely.','')])
 put('common/ideas/hro_history_expansion_ideas.txt','ideas = { country = { '+'\n'.join(ideas)+' } }')
